I was expecting something like below, But as you mentioned that it is kind of temporary code.You can decide whether you want to take it or not.

class ArgvManager {
public:
    ArgvManager (std::vector<std::string>& args) {
        argv_ = new char*[args.size() + 1];
        for (auto i = 0; i < args.size(); i++) {
            argv_[i] = strdup(args[i].c_str());
        }
        argv_[args.size()] = nullptr;
    }

    ~ArgvManager() {
        if (argv_) {
            for (auto i = 0; argv_[i]; i++) {
                free(argv_[i]);
            }
            delete[] argv_;
        }
    }

    char** get() { return argv_; }

private:
    char** argv_ = nullptr;
};

ArgvManager argvMgr(args);
execvp(argvMgr.get()[0], argvMgr.get());
